public class OrderSweepWorker : BackgroundService
{
    private readonly IServiceScopeFactory _scopes;
    private readonly ILogger<OrderSweepWorker> _log;
    private static readonly TimeSpan Interval = TimeSpan.FromSeconds(30);

    public OrderSweepWorker(IServiceScopeFactory scopes, ILogger<OrderSweepWorker> log)
        => (_scopes, _log) = (scopes, log);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var timer = new PeriodicTimer(Interval);
        try
        {
            while (await timer.WaitForNextTickAsync(stoppingToken))
            {
                try
                {
                    using var scope = _scopes.CreateScope();      // fresh scope per pass
                    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

                    var expired = await db.Orders
                        .Where(o => o.Status == OrderStatus.Pending && o.CreatedAt < DateTime.UtcNow.AddMinutes(-15))
                        .ToListAsync(stoppingToken);

                    foreach (var o in expired) o.Status = OrderStatus.Cancelled;
                    await db.SaveChangesAsync(stoppingToken);
                }
                catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
                {
                    break;                       // normal shutdown
                }
                catch (Exception ex)
                {
                    _log.LogError(ex, "Sweep pass failed — will retry next tick");
                    // do not rethrow: default host behavior would STOP the service
                }
            }
        }
        finally
        {
            _log.LogInformation("Order sweep worker stopped");
        }
    }
}

// Program.cs
